@extends('layouts.app')

@section('title', 'Aktivitetsrom – test | INNSATT.NO')
@section('body-class', 'activity-room-page')
@section('disable-analytics', true)

@push('styles')
<style>
.activity-room-shell { margin: 0 auto 2rem; max-width: 1500px; }.activity-room-intro { align-items: start; border-bottom: 4px solid #173f72; display: flex; gap: 1rem; justify-content: space-between; margin-bottom: 1.5rem; padding: 1rem 0; }.activity-room-intro h1 { color: #173f72; font-size: clamp(1.8rem, 3vw, 2.5rem); margin: 0 0 .4rem; }.activity-room-intro p { margin: 0; }.activity-room-now { background: #173f72; border-radius: .35rem; color: #fff; font-size: 1.15rem; font-variant-numeric: tabular-nums; font-weight: 700; min-width: 12rem; padding: .7rem .9rem; text-align: center; }.activity-room-note { background: #fff3cd; border-left: 5px solid #8b6300; font-weight: 600; margin-bottom: 1.25rem; padding: .75rem 1rem; }.activity-room-toolbar { align-items: end; background: #eaf2f8; border: 1px solid #b6cadb; border-radius: .45rem; display: flex; flex-wrap: wrap; gap: .75rem; margin-bottom: 1.25rem; padding: 1rem; }.activity-room-toolbar label, .booking-form label { display: grid; font-weight: 700; gap: .25rem; min-width: 0; }.activity-room-toolbar input { min-width: 16rem; }.activity-room-sound-status { font-weight: 600; margin: 0; }.room-grid { display: grid; gap: 1rem; grid-template-columns: repeat(auto-fit, minmax(380px, 1fr)); }.room-card { border: 2px solid #173f72; border-radius: .5rem; min-width: 0; overflow: hidden; }.room-card__header { align-items: center; background: #173f72; color: #fff; display: flex; gap: .75rem; justify-content: space-between; padding: .7rem .85rem; }.room-card__header h2 { font-size: 1.35rem; margin: 0; min-width: 0; overflow-wrap: anywhere; }.room-card__actions { display: flex; flex-shrink: 0; gap: .4rem; }.room-card__body { min-width: 0; padding: .85rem; }.booking-form { background: #f3f7fa; border: 1px solid #c8d7e4; display: grid; gap: .65rem; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); margin-bottom: .9rem; min-width: 0; padding: .75rem; }.booking-form label { min-width: 0; }.booking-form label:first-child, .booking-form__actions, .booking-form__message { grid-column: 1 / -1; }.booking-form input { box-sizing: border-box; min-width: 0; width: 100%; }.booking-form__actions { display: flex; flex-wrap: wrap; gap: .4rem; }.booking-form__message { color: #8a1c1c; font-weight: 700; margin: 0; }.booking-list { list-style: none; margin: 0; padding: 0; }.booking-row { border-top: 1px solid #cbd5df; display: grid; gap: .65rem; grid-template-columns: 6.75rem minmax(0, 1fr) auto; min-width: 0; padding: .75rem .15rem; }.booking-row:first-child { border-top: 0; }.booking-time { color: #173f72; font-size: 1.05rem; font-variant-numeric: tabular-nums; font-weight: 800; }.booking-person { font-size: 1.05rem; font-weight: 700; overflow-wrap: anywhere; }.booking-meta { color: #334b61; font-size: .9rem; }.booking-actions { align-items: start; display: flex; flex-wrap: wrap; gap: .35rem; justify-content: end; }.booking-status { border-radius: .25rem; display: inline-block; font-size: .82rem; font-weight: 800; margin-top: .25rem; padding: .15rem .4rem; }.booking-status--upcoming { background: #d9edf7; color: #124461; }.booking-status--ongoing { background: #d8f0db; color: #155724; }.booking-status--finished { background: #e6e8eb; color: #374151; }.booking-row--expired { background: #fff0f0; border-left: 5px solid #b42318; padding-left: .5rem; }.booking-row--expired .booking-status { background: #b42318; color: #fff; }.booking-empty { color: #536779; font-style: italic; margin: .6rem 0; }.activity-room-help { color: #536779; font-size: .9rem; margin: 1rem 0 0; }.activity-room-btn { border-radius: .3rem; font-size: .92rem; font-weight: 700; padding: .42rem .65rem; }.activity-room-btn--light { background: #fff; border: 1px solid #fff; color: #173f72; }.activity-room-btn--danger { background: #8a1c1c; border: 1px solid #8a1c1c; color: #fff; }@media (max-width: 700px) { .activity-room-intro { align-items: stretch; flex-direction: column; }.activity-room-now { min-width: 0; }.booking-form { grid-template-columns: 1fr; }.booking-form label, .booking-form label:first-child { grid-column: 1; }.booking-form__actions, .booking-form__message { grid-column: 1; }.room-grid { grid-template-columns: minmax(0, 1fr); }.booking-row { grid-template-columns: 1fr; }.booking-actions { justify-content: start; } }
</style>
@endpush

@section('content')
<div class="container page-container">@include('partials.header')<main class="activity-room-shell" data-activity-rooms><header class="activity-room-intro"><div><h1>Aktivitetsrom – test</h1><p>En enkel dagsoversikt for koordinator på avdelingen.</p></div><div class="activity-room-now" data-current-time aria-live="polite">Laster klokkeslett …</div></header><p class="activity-room-note">Midlertidig oversikt. Opplysningene forsvinner når siden oppdateres eller lukkes.</p><section class="activity-room-toolbar" aria-label="Rom og lyd"><label for="new-room-name">Nytt rom eller aktivitet<input id="new-room-name" data-new-room-name type="text" maxlength="80" placeholder="For eksempel Treningsrom"></label><button class="btn btn-primary activity-room-btn" type="button" data-add-room>Legg til rom</button><button class="btn btn-outline-primary activity-room-btn" type="button" data-enable-sound>Aktiver og test lyd</button><p class="activity-room-sound-status" data-sound-status aria-live="polite">Lyd er ikke aktivert.</p></section><div class="room-grid" data-room-grid></div><p class="activity-room-help">Lydvarsler kan bli forsinket dersom nettleseren eller PC-en går i hvilemodus. Nettleseren kan varsle når du forlater siden så lenge oversikten inneholder rom eller bookinger.</p></main>@include('partials.footer')</div>
@endsection

@push('scripts')
<script>
(() => {
const root=document.querySelector('[data-activity-rooms]');if(!root)return;const rooms=[],endedAudioIds=new Set(),previousStatuses=new Map();let nextId=1,audioContext=null,audioEnabled=false;const nowFormatter=new Intl.DateTimeFormat('nb-NO',{timeZone:'Europe/Oslo',weekday:'long',day:'2-digit',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}),partsFormatter=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Oslo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}),roomGrid=root.querySelector('[data-room-grid]'),nowElement=root.querySelector('[data-current-time]'),soundStatus=root.querySelector('[data-sound-status]');
const osloParts=()=>Object.fromEntries(partsFormatter.formatToParts(new Date()).filter(({type})=>type!=='literal').map(({type,value})=>[type,Number(value)]));const timelineNow=()=>{const p=osloParts();return Date.UTC(p.year,p.month-1,p.day,p.hour,p.minute,p.second)};const timeToMinutes=time=>{const match=/^(\d{2}):(\d{2})$/.exec(time||'');return !match||Number(match[1])>23||Number(match[2])>59?null:Number(match[1])*60+Number(match[2])};const timeFromMinutes=minutes=>`${String(Math.floor((minutes%1440+1440)%1440/60)).padStart(2,'0')}:${String((minutes%60+60)%60).padStart(2,'0')}`;const bookingTimes=booking=>{const minutes=timeToMinutes(booking.start);if(minutes===null)return null;const p=osloParts(),start=Date.UTC(p.year,p.month-1,p.day,Math.floor(minutes/60),minutes%60);return{start,end:start+booking.duration*60000}};const bookingStatus=booking=>{const times=bookingTimes(booking),now=timelineNow();return now<times.start?'upcoming':now<times.end?'ongoing':'finished'};const statusText=booking=>{const status=bookingStatus(booking);if(status==='upcoming')return'Kommende';if(status==='ongoing'){const left=Math.max(0,Math.ceil((bookingTimes(booking).end-timelineNow())/60000));return`Pågår – ${left} min igjen`}return booking.acknowledged?'Ferdig – kvittert':'Tiden er ute – kvitter'};const overlaps=(room,candidate,exceptId=null)=>{const candidateTimes=bookingTimes(candidate);return room.bookings.some(booking=>{if(booking.id===exceptId)return false;const times=bookingTimes(booking);return candidateTimes.start<times.end&&times.start<candidateTimes.end})};const makeButton=(label,className,action)=>{const button=document.createElement('button');button.type='button';button.className=className;button.textContent=label;button.addEventListener('click',action);return button};
const playTone=()=>{if(!audioEnabled||!audioContext)return;const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.type='sine';oscillator.frequency.value=880;gain.gain.setValueAtTime(.08,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.25);oscillator.connect(gain).connect(audioContext.destination);oscillator.start();oscillator.stop(audioContext.currentTime+.25)};const enableSound=async()=>{try{audioContext=audioContext||new(window.AudioContext||window.webkitAudioContext)();await audioContext.resume();audioEnabled=true;playTone();soundStatus.textContent='Lyd er aktivert. Kort testtone spilt.'}catch(_){soundStatus.textContent='Kunne ikke aktivere lyd i denne nettleseren.'}};
function refreshLiveData(){nowElement.textContent=nowFormatter.format(new Date()).replace(/^./,letter=>letter.toUpperCase());rooms.forEach(room=>room.bookings.forEach(booking=>{const key=`${room.id}-${booking.id}`,row=roomGrid.querySelector(`[data-booking-id="${key}"]`);if(!row)return;const status=bookingStatus(booking),tag=row.querySelector('[data-booking-status]');row.classList.toggle('booking-row--expired',status==='finished'&&!booking.acknowledged);tag.className=`booking-status booking-status--${status}`;tag.textContent=statusText(booking);const oldStatus=previousStatuses.get(key);if(status==='finished'&&oldStatus&&oldStatus!=='finished'&&!endedAudioIds.has(key)){endedAudioIds.add(key);playTone()}previousStatuses.set(key,status)}))}
function saveBooking(room,booking,form,message){const person=form.querySelector('[name="person"]').value.trim(),start=form.querySelector('[name="start"]').value,duration=Number(form.querySelector('[name="duration"]').value);if(!person){message.textContent='Skriv hvem som skal bruke rommet.';return}if(timeToMinutes(start)===null){message.textContent='Oppgi et gyldig startklokkeslett.';return}if(!Number.isInteger(duration)||duration<1||duration>1440){message.textContent='Varighet må være et helt antall minutter fra 1 til 1440.';return}const entry={id:booking?booking.id:nextId++,person,start,duration,acknowledged:booking?booking.acknowledged:false},warning=overlaps(room,entry,booking&&booking.id)?'Booking lagret. Den overlapper med en annen booking i dette rommet.':'';if(booking)Object.assign(booking,entry);else room.bookings.push(entry);renderRooms();if(warning)roomGrid.querySelector(`[data-room-id="${room.id}"] [data-booking-message]`).textContent=warning}
function editBooking(room,booking,form){form.querySelector('[name="person"]').value=booking.person;form.querySelector('[name="start"]').value=booking.start;form.querySelector('[name="duration"]').value=booking.duration;form.dataset.editingId=booking.id;form.querySelector('[data-save-booking]').textContent='Lagre endring';form.querySelector('[data-cancel-edit]').hidden=false;form.querySelector('[data-booking-message]').textContent='';form.querySelector('[name="person"]').focus()}
function buildRoomCard(room){const card=document.createElement('section');card.className='room-card';card.dataset.roomId=room.id;const header=document.createElement('header');header.className='room-card__header';const heading=document.createElement('h2');heading.textContent=room.name;const actions=document.createElement('div');actions.className='room-card__actions';actions.append(makeButton('Endre navn','activity-room-btn activity-room-btn--light',()=>{const name=window.prompt('Nytt navn på rommet:',room.name);if(name!==null&&name.trim()){room.name=name.trim().slice(0,80);renderRooms()}}),makeButton('Slett rom','activity-room-btn activity-room-btn--danger',()=>{if(window.confirm(`Slette ${room.name} med alle bookingene?`)){rooms.splice(rooms.indexOf(room),1);renderRooms()}}));header.append(heading,actions);const body=document.createElement('div');body.className='room-card__body';const form=document.createElement('form');form.className='booking-form';form.noValidate=true;form.innerHTML='<label>Hvem skal bruke rommet?<input name="person" type="text" maxlength="120" required></label><label>Start<input name="start" type="time" required></label><label>Varighet (min)<input name="duration" type="number" min="1" max="1440" step="1" value="60" required></label><div class="booking-form__actions"><button class="btn btn-primary activity-room-btn" type="submit" data-save-booking>Legg til booking</button><button class="btn btn-outline-secondary activity-room-btn" type="button" data-cancel-edit hidden>Avbryt</button></div><p class="booking-form__message" data-booking-message aria-live="polite"></p>';form.addEventListener('submit',event=>{event.preventDefault();saveBooking(room,room.bookings.find(({id})=>String(id)===form.dataset.editingId),form,form.querySelector('[data-booking-message]'))});form.querySelector('[data-cancel-edit]').addEventListener('click',()=>{form.reset();form.querySelector('[name="duration"]').value='60';form.dataset.editingId='';form.querySelector('[data-save-booking]').textContent='Legg til booking';form.querySelector('[data-cancel-edit]').hidden=true;form.querySelector('[data-booking-message]').textContent=''});body.append(form);const list=document.createElement('ul');list.className='booking-list';room.bookings.sort((a,b)=>timeToMinutes(a.start)-timeToMinutes(b.start)).forEach(booking=>{const status=bookingStatus(booking),key=`${room.id}-${booking.id}`,row=document.createElement('li');row.className=`booking-row${status==='finished'&&!booking.acknowledged?' booking-row--expired':''}`;row.dataset.bookingId=key;const time=document.createElement('div');time.className='booking-time';time.textContent=`${booking.start}–${timeFromMinutes(timeToMinutes(booking.start)+booking.duration)}`;const description=document.createElement('div'),person=document.createElement('div');person.className='booking-person';person.textContent=booking.person;const meta=document.createElement('div');meta.className='booking-meta';meta.textContent=`${booking.duration} minutter${overlaps(room,booking,booking.id)?' · Overlapper annen booking':''}`;const tag=document.createElement('span');tag.dataset.bookingStatus='';tag.className=`booking-status booking-status--${status}`;tag.textContent=statusText(booking);description.append(person,meta,tag);const rowActions=document.createElement('div');rowActions.className='booking-actions';rowActions.append(makeButton('Endre','btn btn-outline-primary activity-room-btn',()=>editBooking(room,booking,form)));if(status==='finished'&&!booking.acknowledged)rowActions.append(makeButton('Kvitter ut','btn btn-warning activity-room-btn',()=>{booking.acknowledged=true;renderRooms()}));rowActions.append(makeButton('Slett','btn btn-outline-danger activity-room-btn',()=>{if(window.confirm('Slette denne bookingen?')){room.bookings.splice(room.bookings.indexOf(booking),1);renderRooms()}}));row.append(time,description,rowActions);list.append(row)});if(!room.bookings.length){const empty=document.createElement('p');empty.className='booking-empty';empty.textContent='Ingen bookinger ennå.';body.append(empty)}else body.append(list);card.append(header,body);return card}
function renderRooms(){roomGrid.replaceChildren(...rooms.map(buildRoomCard));refreshLiveData()}
root.querySelector('[data-add-room]').addEventListener('click',()=>{const input=root.querySelector('[data-new-room-name]'),name=input.value.trim();if(!name){input.setCustomValidity('Skriv et navn på rommet eller aktiviteten.');input.reportValidity();return}input.setCustomValidity('');rooms.push({id:nextId++,name:name.slice(0,80),bookings:[]});input.value='';renderRooms()});root.querySelector('[data-new-room-name]').addEventListener('input',event=>event.target.setCustomValidity(''));root.querySelector('[data-enable-sound]').addEventListener('click',enableSound);window.addEventListener('beforeunload',event=>{if(rooms.length){event.preventDefault();event.returnValue=''}});document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshLiveData()});window.setInterval(refreshLiveData,1000);renderRooms();
})();
</script>
@endpush
